     */
    @Transactional
    public Optional<Long> refundCredit(Long clientId, BigDecimal refundAmount, Currency refundIn, LocalDate date) {
        Optional<Client> client = clients.findById(clientId);
        if (client.isEmpty()) {
            return Optional.empty();
